import {escape} from './html.js';
import {byteMascot} from './mascot.js';
import {courseRoute} from './navigation.js';
export const avatars={brain:'🧠',bolt:'⚡',knight:'♞',leaf:'🌱',star:'⭐',rocket:'🚀'};
export const syncLabel=status=>({guest:'Progres tamu di browser ini',syncing:'Menyinkronkan progres…',pending:'Perubahan tersimpan di perangkat · menunggu sinkronisasi',synced:'Progres tersinkron ke akun',error:'Belum tersinkron · salinan perangkat tetap aman'})[status]??'Menyiapkan akun…';
const input=(name,label,type='text',autocomplete='',extra='')=>`<label class="account-field"><span>${label}</span><input name="${name}" type="${type}" autocomplete="${autocomplete}" required ${extra}></label>`;
export function accountMarkup({screen,user,profile,stats,progress,courses,status,config,message='',busy=false,importAvailable=false,importPending=false,recoveryAllowed=false}) {
  const notification=`<p id="account-message" class="account-message" role="status" ${message?'':'hidden'}>${escape(message)}</p>`;
  if(screen==='profile' && user) {
    const name=profile?.display_name??user.user_metadata?.display_name??'Pelajar';
    return `<div class="page account-page"><header class="account-heading"><div><span class="eyebrow">Ruang belajarmu</span><h1 tabindex="-1">Profil</h1><p>Langkah kecilmu, tersimpan bersama akunmu.</p></div><button class="text-button" data-account="logout" ${busy?'disabled':''}>Keluar akun</button></header>
      <section class="profile-identity"><span class="profile-avatar" aria-hidden="true">${avatars[profile?.avatar_id]??avatars.brain}</span><div><h2>${escape(name)}</h2><p>${escape(user.email??'')}</p><small>Bergabung ${escape(new Date(profile?.created_at??user.created_at).toLocaleDateString('id-ID',{month:'long',year:'numeric'}))}</small></div></section>
      <div class="profile-stats"><div><strong>${stats.xp}</strong><span>Total XP</span></div><div><strong>${stats.solvedCount}</strong><span>Latihan dikuasai</span></div><div><strong>${stats.streak}</strong><span>Hari streak</span></div></div>
      <section class="account-sync"><div><strong data-sync-status>${syncLabel(status)}</strong><p>Progres tiap pelajaran mengikuti akun ini.</p></div><button class="text-button" data-account="sync" ${busy?'disabled':''}>Sinkronkan</button></section>${notification}
      ${importAvailable||importPending?`<section class="guest-import"><h2>Progres tamu ditemukan</h2><p>Gabungkan progres tamu di perangkat ini ke akunmu. XP dari soal yang sama dihitung sekali. Setelah dicadangkan, progres tamu ini hanya dapat diimpor oleh akun ini.</p><button class="primary" data-account="import" ${busy||status!=='synced'?'disabled':''}>${importPending?'Lanjutkan impor progres':'Gabungkan progres tamu'}</button></section>`:''}
      <section class="profile-courses"><h2>Perjalanan belajar</h2>${courses.map(c=>`<a class="profile-course" href="${courseRoute(c.id)}" data-course="${c.id}"><span class="profile-course-symbol">${escape(c.symbol)}</span><span><strong>${escape(c.title)}</strong><small>${progress[c.id].solvedCount}/${c.exerciseCount} latihan · ${progress[c.id].xp} XP</small><progress max="${c.exerciseCount}" value="${progress[c.id].solvedCount}" aria-label="Progres ${escape(c.title)}"></progress></span><span aria-hidden="true">→</span></a>`).join('')}</section>
      <section class="profile-edit"><h2>Jadikan milikmu</h2><form id="account-form" data-mode="profile">${input('name','Nama tampilan','text','nickname',`maxlength="60" value="${escape(name)}"`)}<fieldset class="avatar-picker"><legend>Pilih avatar</legend>${Object.entries(avatars).map(([id,symbol])=>`<label><input type="radio" name="avatar" value="${id}" ${id===(profile?.avatar_id??'brain')?'checked':''}><span aria-label="${id}">${symbol}</span></label>`).join('')}</fieldset><button class="primary" ${busy?'disabled':''}>${busy?'Menyimpan…':'Simpan profil'}</button></form></section></div>`;
  }
  const mode=screen==='profile'?'login':screen;
  const headings={login:['Selamat datang kembali','Masuk untuk membawa progresmu ke mana saja.'],register:['Mulai petualanganmu','Satu akun untuk semua pelajaran.'],forgot:['Lupa kata sandi?','Kami kirimkan tautan untuk membuat kata sandi baru.'],recovery:['Kata sandi baru','Buat kata sandi yang aman untuk akunmu.']};
  const [heading,lead]=headings[mode]??headings.login;
  return `<div class="page auth-page"><section class="auth-intro">${byteMascot('idle')}<span class="eyebrow">Flash Brains · Akun</span><h1 tabindex="-1">${heading}</h1><p>${lead}</p></section><section class="auth-panel" aria-label="${heading}">
    ${['login','register'].includes(mode)?`<button type="button" class="google-button" data-account="google" ${busy||!config?.googleEnabled?'disabled':''}><span class="google-letter" aria-hidden="true">G</span>Lanjutkan dengan Google</button>${!config?.googleEnabled?'<p class="provider-note">Google Login sedang disiapkan.</p>':''}<div class="auth-divider"><span>atau dengan email</span></div>`:''}
    ${notification}${!config?'<p class="provider-note">Layanan akun belum tersedia. Kamu tetap bisa belajar sebagai tamu.</p>':''}
    ${mode==='recovery'&&!recoveryAllowed?'<p>Buka tautan pemulihan dari email untuk mengubah kata sandi.</p><a class="text-button" href="#/lupa-password">Minta tautan baru</a>':`<form id="account-form" data-mode="${mode}">${mode==='register'?input('name','Nama tampilan','text','nickname','maxlength="60"'):''}${mode!=='recovery'?input('email','Email','email','email','maxlength="254"'):''}${mode!=='forgot'?input('password',mode==='recovery'?'Kata sandi baru':'Kata sandi','password',mode==='login'?'current-password':'new-password','minlength="8" maxlength="128"'):''}${['register','recovery'].includes(mode)?input('confirm','Ulangi kata sandi','password','new-password','minlength="8" maxlength="128"'):''}${mode==='login'?'<a class="forgot-link" href="#/lupa-password">Lupa kata sandi?</a>':''}<button class="primary account-submit" ${busy||!config?'disabled':''}>${busy?'Sebentar…':({login:'Masuk',register:'Buat akun',forgot:'Kirim tautan pemulihan',recovery:'Simpan kata sandi'})[mode]}</button></form>`}
    ${['register','forgot'].includes(mode)&&config&&!config.emailDeliveryReady?'<p class="provider-note">Pengiriman email publik sedang disiapkan. Konfirmasi pendaftaran dan pemulihan belum tersedia untuk umum.</p>':''}
    <p class="auth-switch">${mode==='login'?'Belum punya akun? <a href="#/daftar">Daftar</a>':mode==='register'?'Sudah punya akun? <a href="#/login">Masuk</a>':'<a href="#/login">Kembali ke halaman masuk</a>'}</p></section><a class="guest-link" href="#/">Lanjut belajar sebagai tamu <span aria-hidden="true">→</span></a><p class="auth-footnote">Pelajaran selalu terbuka. Login membantu menyimpan perjalananmu.</p></div>`;
}
